{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter. Implements export_csv per TASK.txt."""


def _escape(value):
    """Format one CSV field with minimal RFC 4180 quoting."""
    if value is None:
        text = ""
    else:
        text = str(value)
    if any(ch in text for ch in (",", '"', "\r", "\n")):
        return '"' + text.replace('"', '""') + '"'
    return text


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    ``rows`` is an iterable of mappings; ``columns`` is an ordered iterable
    of unique string column names. Returns a str with a header record then
    one record per row, comma-delimited with CRLF endings. Missing fields
    and None become empty strings; other values become str(value).
    Duplicate or non-string column names raise ValueError. Inputs are not
    mutated and may be one-shot iterables.
    """
    column_list = list(columns)
    seen = set()
    for name in column_list:
        if not isinstance(name, str):
            raise ValueError("column names must be strings, got %r" % (name,))
        if name in seen:
            raise ValueError("duplicate column name: %r" % (name,))
        seen.add(name)

    parts = [",".join(_escape(name) for name in column_list) + "\r\n"]
    for row in rows:
        parts.append(
            ",".join(_escape(row.get(name)) for name in column_list) + "\r\n"
        )
    return "".join(parts)
"}
